S = '(Sweigart, 2025)'; PSF = '(Python Software Foundation, 2026)'; IN22 = '(Inada, 2022)'; IN19 = '(Inada, 2019)'; PI = '(Pitrou, 2012)'; CA = '(Cannon, 2016)'
BODY = {
 'Filepaths': 'Filepaths, the names that say where a file lies, are the base of Chapter 10 (Sweigart, 2025).',
 'PathObjects': 'The chapter builds paths with the Path() function of the pathlib module, joins them with the / operator and explains the separators of the operating systems (Sweigart, 2025).',
 'PathConstruction': "Path('spam', 'bacon', 'eggs') joins the names with the separator of the operating system: the chapter, run on Windows, prints WindowsPath('spam/bacon/eggs') and str() of it as 'spam\\\\bacon\\\\eggs', and on macOS or Linux a PosixPath and 'spam/bacon/eggs' (Sweigart, 2025); on the Linux machine of this study the type of Path('spam', 'bacon', 'eggs') was PosixPath, and the Windows outputs were reproduced with PureWindowsPath, which gives PureWindowsPath('spam/bacon/eggs') and 'spam\\\\bacon\\\\eggs', the POSIX class giving 'spam/bacon/eggs'; the chapter says in one sentence that Path() returns a string and in the next that it returns a WindowsPath object, and it is the object that is returned (Python Software Foundation, 2026).",
 'PathJoining': "Path('spam') / 'bacon' / 'eggs' gives the same path as Path('spam') / Path('bacon/eggs') and Path('spam') / Path('bacon', 'eggs'), and 'spam' / 'bacon' raises TypeError: unsupported operand type(s) for /: 'str' and 'str', because one of the first two operands must be a path; the / operator replaces os.path.join() (Sweigart, 2025); 'spam' / Path('bacon') also works, Path('spam').joinpath('bacon', 'eggs') is the same join as a method, and a right operand that is absolute replaces what lies to its left, Path('spam') / '/etc' being PosixPath('/etc') and os.path.join('spam', '/etc') being '/etc' (Python Software Foundation, 2026).",
 'PathFlavours': "On Windows the backslash separates folders and is not allowed in a filename, and on macOS and Linux it is an ordinary character, so the chapter advises forward slashes in source code, which pathlib turns into the right separator; the loop over accounts.txt, details.csv and invite.docx with Path(r'C:\\Users\\Al', filename) prints C:\\Users\\Al\\accounts.txt and the two like lines (Sweigart, 2025); run here, PureWindowsPath(r'spam\\eggs').parts was ('spam', 'eggs') and PurePosixPath(r'spam\\eggs').parts was ('spam\\\\eggs',), one name (Python Software Foundation, 2026).",
 'WorkingLocations': 'Where a program is running and where the user keeps files decide how a path is read (Sweigart, 2025).',
 'WorkingDirectory': "Every program has a current working directory, and a name that does not begin at the root folder is read from it; Path.cwd() returns it as a path object, os.getcwd() as a string, and os.chdir() changes it, there being no pathlib function for that, and os.chdir() to a missing folder raises FileNotFoundError (Sweigart, 2025); run here, Path.cwd().name was 'walnut' after os.chdir('delicious/walnut'), the error read [Errno 2] No such file or directory: 'ThisFolderDoesNotExist' where the chapter prints the Windows text [WinError 2] The system cannot find the file specified, and hasattr(Path, 'chdir') was False (Python Software Foundation, 2026).",
 'HomeDirectory': "Path.home() returns the home folder of the user, C:\\Users\\Al in the chapter's example, under C:\\Users on Windows, /Users on macOS and often /home on Linux (Sweigart, 2025); run here the result was absolute and equal to Path(os.path.expanduser('~')) and to Path('~').expanduser(), and the documentation says a RuntimeError is raised if the home directory cannot be resolved (Python Software Foundation, 2026).",
 'AbsoluteVersusRelative': "An absolute path begins with the root folder, C:\\ on Windows and / on macOS and Linux, and a relative path is relative to the current working directory; Path.cwd().is_absolute() is True and Path('spam/bacon/eggs').is_absolute() is False, Path.cwd() / Path('my/relative/path') and Path('my/relative/path').absolute() give the same absolute path, and the same relative path can be put after Path.home() instead (Sweigart, 2025); run here absolute() was equal to Path.cwd() / r, and it leaves .. in place, Path('docs/../setup.py').absolute() ending in docs/../setup.py while resolve() gave setup.py; for the Windows kind a path needs a drive as well as a root, so PureWindowsPath('C:/Users') was absolute and PureWindowsPath('/a/b') and PureWindowsPath('C:') were not, where PurePosixPath('/a/b') was (Python Software Foundation, 2026).",
 'DotAndDotDot': "A single dot is the name of this folder and two dots the name of the parent folder; they are not real folders but special names, and the .\\ at the start of a relative path is optional, so .\\spam.txt and spam.txt are the same file (Sweigart, 2025); run here Path('./spam.txt') == Path('spam.txt') was True and str of it 'spam.txt', str(Path('a/../b')) kept the two dots as 'a/../b', and from the folder bacon/eggs Path('..').resolve().name was 'bacon' and Path('../..').resolve() was the parent of the parent (Python Software Foundation, 2026).",
 'PathAnatomy': 'A path breaks into parts that other paths are built from (Sweigart, 2025).',
 'PathAttributes': "For Path('C:/Users/Al/spam.txt') the anchor is 'C:\\\\', the name 'spam.txt', the stem 'spam', the suffix '.txt' and the drive 'C:', and the parent is another path, WindowsPath('C:/Users/Al'); the attributes are strings except parent (Sweigart, 2025); reproduced with PureWindowsPath; the chapter says that macOS and Linux path objects have no drive attribute, yet PurePosixPath('/home/al/spam.txt') had the anchor '/' and the drive '', an empty string, and archive.tar.gz having the suffix '.gz', the suffixes ['.tar', '.gz'] and the stem 'archive.tar' (Python Software Foundation, 2026).",
 'PathParts': "The parts attribute is a tuple of strings, ('C:\\\\', 'Users', 'Al', 'spam.txt') for the chapter's path, so parts[3] is 'spam.txt' and parts[0:2] is ('C:\\\\', 'Users'), and the parents attribute, different from parent, is indexed by an integer, parents[0] being C:/Users/Al and parents[2] C:/ for a path C:/Users/Al/Desktop (Sweigart, 2025); run here len(parents) was 3 for that path and parents of the POSIX path '/home/al/spam.txt' ended at '/', the last step following the parents up to the root folder (Python Software Foundation, 2026).",
 'DerivedPaths': 'A new path can be made from an existing one without touching any file (Python Software Foundation, 2026).',
 'PathDerivation': "with_suffix('.csv') turned /home/al/reports/spam.txt into /home/al/reports/spam.csv, with_name('eggs.txt') into /home/al/reports/eggs.txt and relative_to('/home/al') into reports/spam.txt, while relative_to('/usr') raised ValueError, and p.parent / (p.stem + '_backup' + p.suffix) gave /home/al/reports/spam_backup.txt; the chapter as read does not present these methods (Sweigart, 2025) (Python Software Foundation, 2026).",
 'Folders': 'Folders are created, searched and inspected with os, os.path and pathlib (Sweigart, 2025).',
 'CreatingFolders': 'The chapter creates folders with os.makedirs() and with the mkdir() method (Sweigart, 2025).',
 'MakingFolders': "os.makedirs('C:\\\\delicious\\\\walnut\\\\waffles') creates the folder delicious, the folder walnut in it and the folder waffles in that, all the intermediate folders, and Path(r'C:\\Users\\Al\\spam').mkdir() makes one folder, which needs parents=True to create the folders above it (Sweigart, 2025); run here a second os.makedirs() of the same path raised FileExistsError and did not with exist_ok=True, Path('a/b').mkdir() without the folder a raised FileNotFoundError and with parents=True made both, and a second Path('spam').mkdir() raised FileExistsError unless exist_ok=True was given (Python Software Foundation, 2026).",
 'FindingFiles': 'The chapter finds the files of a folder with glob patterns (Sweigart, 2025).',
 'GlobPatterns': "In a glob pattern * matches any text and ? exactly one character, so '*.txt' matches the names ending in .txt, 'project?.txt' matches project1.txt, project2.txt and projectX.txt and '*' matches all names; glob() on a folder's path gives a generator that list() turns into a list of paths, or a for loop goes through (Sweigart, 2025); run on a folder of eleven files, '*.txt' gave catproject5.txt, project1.txt, project10.txt, project2.txt, projectX.txt and zzz.txt, 'project?.txt' did not match project10.txt, '*project?.*' also matched secret_project7.docx, '[0-9]*' matched 1.png and 22-ap.pdf, '*' included the folder sub, the file notes.TXT matched only with case_sensitive=False on this Linux machine, sorted() was needed because the order is arbitrary, the object returned was a map, not the generator of the chapter's print, and a second list() of it was empty (Python Software Foundation, 2026).",
 'RecursiveGlob': "The chapter's patterns look at one folder; with a ** segment, glob('**/*.txt') and rglob('*.txt') give the same paths from the whole tree below a folder, which gave top.txt, sub/inner.txt and sub/deeper/deep.txt here, while '*/*.txt' gave only sub/inner.txt and a pattern ending in a slash, 'sub/', gave only the folder sub; the chapter as read does not present rglob() (Sweigart, 2025) (Python Software Foundation, 2026).",
 'FileInformation': 'A program asks the file system whether a path exists and what it holds (Sweigart, 2025).',
 'PathValidity': "exists() is True if the path exists, is_file() if it exists and is a file, and is_dir() if it exists and is a folder, and all are False for a path that does not exist, so Path('D:/').exists() is False when no flash drive is attached; the older os.path.exists(), isfile() and isdir() act the same and accept Path objects since Python 3.6 (Sweigart, 2025); run here a file gave True, True, False, a folder True, False, True and a missing path False three times, the os.path functions agreeing, and the documentation adds that in Python 3.14 these methods return False instead of raising any OSError, which needs a path whose check is refused and was not run, the session being a superuser (Python Software Foundation, 2026).",
 'FileStat': "stat() returns a stat_result object whose st_size is the size of the file in bytes, which divided by 1024, 1024 ** 2 or 1024 ** 3 gives kilobytes, megabytes or gigabytes, st_mtime the last modified time, st_ctime the creation time on Windows and the time of the last change of the metadata elsewhere, and st_atime the last access, all in seconds since 1 January 1970, which time.asctime(time.localtime(...)) turns into text (Sweigart, 2025); run here a file holding 'Hello, world!' had st_size 13, which is 0.0126953125 KB, the timestamp set to 1712627129 with os.utime() read back as 1712627129.0 and time.asctime(time.gmtime(...)) gave 'Tue Apr  9 01:45:29 2024', five hours after the 'Mon Apr  8 20:45:29 2024' that the chapter prints for the same second in its own time zone; the documentation deprecates st_ctime on Windows since Python 3.12 in favour of st_birthtime, which was not run on Windows (Python Software Foundation, 2026).",
 'TextFiles': 'Plain text files are read and written whole with pathlib, or opened as file objects (Sweigart, 2025).',
 'WholeFileMethods': 'The pathlib methods read_text() and write_text() handle a whole text file in one call (Sweigart, 2025).',
 'WriteAndReadText': "Path('spam.txt').write_text('Hello, world!') creates the file, or overwrites it, and returns 13, the number of characters written, and read_text() returns 'Hello, world!' (Sweigart, 2025); run here write_text('caf\\u00e9', encoding='utf-8') returned 4 while the file held 5 bytes, b'caf\\xc3\\xa9', a second write_text('again') returned 5 and replaced the first content, and the documentation says the file is opened and closed by each call (Python Software Foundation, 2026).",
 'PlainVersusBinaryFiles': "Plaintext files hold only basic text characters, with no font, size or colour, and the .txt and .py files are examples; all other files, such as word processing documents, PDFs, images, spreadsheets and programs, are binary files that look like nonsense in Notepad, and the chapter reads and writes only plaintext directly, leaving the binary kinds to modules such as shelve (Sweigart, 2025); run here read_bytes() and write_bytes() returned b'\\x00\\x01\\xff' and 3, open(name, 'rb') returned a BufferedReader whose read() gave bytes, open(name, 'rb', encoding='utf-8') raised ValueError: binary mode doesn't take an encoding argument and writing a string to a file opened with 'wb' raised TypeError: a bytes-like object is required, not 'str' (Python Software Foundation, 2026).",
 'OpenedFiles': 'open() returns a file object that is read, written and closed (Sweigart, 2025).',
 'OpenAndModes': "open('hello.txt', encoding='UTF-8') opens in read mode, the default, and 'r' can be given; 'w' overwrites and 'a' appends, both creating a missing file; in the chapter's session bacon_file.write('Hello, world!\\n') returned 14 and write('Bacon is not a vegetable.') returned 25, and reading the file back printed the two lines (Sweigart, 2025); run here these values were 14 and 25 and the content read as printed, opening with 'w' emptied the file at once, 'a' created fresh.txt, writing to a file opened for reading raised io.UnsupportedOperation: not writable and reading one opened for writing raised io.UnsupportedOperation: not readable, a missing file raised FileNotFoundError, 'x' on an existing file raised FileExistsError and on a new one created it, and 'r+' read 'made' then wrote, the class being a kind of OSError; the chapter's practice question names three modes, 'r', 'w' and 'a' (Python Software Foundation, 2026).",
 'ReadMethods': "read() returns the contents of the file as one string and readlines() a list of strings, one for each line, in which each string but the last ends in a newline (Sweigart, 2025); run on the chapter's sonnet file readlines() returned the four strings printed there, a second readlines() returned [] and read() returned '' because the position was at the end, after seek(0) readline() returned the first line with its newline, read(5) 'I all' and read(3) ' al', read() after seek(0) had 171 characters, and a readline() loop counted 4 lines and then returned '' (Python Software Foundation, 2026).",
 'LineIteration': "The chapter reads a file whole with read() or readlines(), and a file object can also be looped over one line at a time, each line keeping its newline, which never holds more than one line in memory; run on the sonnet file the loop gave the lines 'When, in dis', 'I all alone ', 'And trouble ' and 'And look upo' cut to twelve characters, and the last line had no newline because the file does not end with one; the chapter as read does not present it (Sweigart, 2025) (Python Software Foundation, 2026).",
 'WriteMethod': "write() writes a string and returns the number of characters, including the newline, and unlike print() it does not add a newline, so the program must add it (Sweigart, 2025); run here write('a') followed by write('b') and print('c', file=f) gave the file 'abc\\n', write(42) raised TypeError: write() argument must be str, not int, and writelines(['x\\n', 'y\\n']) wrote two lines (Python Software Foundation, 2026).",
 'CloseMethod': "Every file opened with open() needs close() called on it, which the chapter asks for before a file is opened again (Sweigart, 2025); run here a file opened for writing had closed False, write('data') returned 4, another reader of the same file saw '' until close() was called and then 'data', and a write to the closed file raised ValueError: I/O operation on closed file; the tutorial warns that a write without with or close() might not be completely written to the disk even if the program exits successfully (Python Software Foundation, 2026).",
 'TextEncoding': 'The encoding and line-ending arguments decide how characters become bytes in a file (Sweigart, 2025).',
 'EncodingArgument': "The encoding argument names the encoding used to convert bytes to a text string; the chapter says it is almost always 'utf-8', the default on macOS and Linux, that Windows defaults to 'cp1252', and that it is a good habit to pass encoding='utf-8' to open() in plaintext modes (Sweigart, 2025); the documentation says the default is platform dependent, whatever locale.getencoding() returns, and recommends UTF-8; run here the bytes b'caf\\xc3\\xa9' read as 'caf\\xe9' with utf-8, as 'caf\\xc3\\xa9' with latin-1 and cp1252, raised UnicodeDecodeError: 'ascii' codec can't decode byte 0xc3 in position 3: ordinal not in range(128) with ascii, writing it with ascii raised UnicodeEncodeError, and an open() without the argument gave the locale's encoding; with -X warn_default_encoding a call of open() without encoding drew an EncodingWarning and a call with it drew none, and Python 3.15 will make UTF-8 mode the default, which is not so in 3.14.4 (Python Software Foundation, 2026) (Inada, 2019) (Inada, 2022).",
 'NewlineTranslation': "In text mode Python reads the line endings \\n, \\r and \\r\\n as \\n and, when writing, turns \\n into the line ending of the system, and the newline argument changes this; the chapter as read does not present the newline argument (Sweigart, 2025); the tutorial warns that the translation corrupts binary data like JPEG or EXE files, and run here write_text('a\\nb', newline='\\r\\n') left the bytes b'a\\r\\nb', read_text() gave 'a\\nb' and read_text(newline='') 'a\\r\\nb', and open(..., newline='') wrote b'a\\nb\\r\\n' unchanged (Python Software Foundation, 2026).",
 'DecodingErrors': "The errors argument chooses what happens to bytes that cannot be decoded: the default 'strict' raises, 'replace' inserts U+FFFD, 'ignore' drops them and 'surrogateescape' keeps them so that they can be written back; run here open of b'caf\\xc3\\xa9' with encoding='ascii', errors='replace' read 'caf\\ufffd\\ufffd'; the chapter as read does not present the errors argument (Sweigart, 2025) (Python Software Foundation, 2026).",
 'AutomaticClosing': 'The with statement closes a file on every way out of a block (Sweigart, 2025).',
 'WithStatement': "A with statement creates a context manager and runs its block, closing the file when execution leaves the block by a return statement, an unhandled exception or otherwise, so the code with open('data.txt', 'w', encoding='UTF-8') as file_obj: needs no close() (Sweigart, 2025); the reference says __exit__ is always called once __enter__ has returned, and run here a file was closed after a block that ended, after one that raised RuntimeError, and after a function that returned from inside the block, the file object having both __enter__ and __exit__ (Python Software Foundation, 2026).",
 'ClosedFileError': 'After the block of a with statement, or after close(), the file object cannot be used: a read or write raises ValueError: I/O operation on closed file, and the attribute closed is True; the chapter as read does not show the error (Sweigart, 2025) (Python Software Foundation, 2026).',
 'SavedData': 'Variables can outlive the program by being saved to a file (Sweigart, 2025).',
 'Shelves': 'The shelve module saves the values of variables in a binary shelf file and brings them back in a later run (Sweigart, 2025).',
 'ShelveOpen': "shelve.open('mydata') returns a shelf value, to which shelf_file['cats'] = ['Zophie', 'Pooka', 'Simon'] stores a list under a key, like a dictionary, and close() ends the use; reopening gives the list again, and type(shelf_file) is <class 'shelve.DbfilenameShelf'> (Sweigart, 2025); run here all of this held, and the folder held the single file mydata; the documentation names the context-manager form with shelve.open('spam') as db and says not to rely on a shelf being closed automatically (Python Software Foundation, 2026).",
 'ShelfAsDictionary': "A shelf has keys() and values() like a dictionary, and list(shelf_file.keys()) is ['cats'] and list(shelf_file.values()) is [['Zophie', 'Pooka', 'Simon']] (Sweigart, 2025); run here the views were of the type KeysView, 'cats' in a shelf was True and len() was 1, del removed a key, reading a key that is not there raised KeyError, a key that is not a string raised AttributeError: 'int' object has no attribute 'encode', a tuple, a set and a nested dictionary came back equal, each read of a key gave an equal copy and not the same object, and a shelf that is closed raised ValueError: invalid operation on closed shelf (Python Software Foundation, 2026).",
 'ShelfWriteback': "The chapter as read stores values but does not show changing one: run here a shelf holding ['Zophie'] still held ['Zophie'] after shelf['cats'].append('Pooka') was called on a reopened shelf, held ['Zophie', 'Pooka'] when the list was assigned back to the key, and gained 'Simon' in the same way when the shelf was opened with writeback=True; the documentation explains that a shelf cannot know when a mutable entry is modified, and that writeback=True caches every entry accessed and can use much memory and make closing slow (Sweigart, 2025) (Python Software Foundation, 2026).",
 'ShelfBackend': 'The chapter says that after the first shelf the folder holds mydata.bak, mydata.dat and mydata.dir on Windows, a single mydata.db on macOS and a single mydata on Linux, and that the format is not important (Sweigart, 2025); the documentation says that the files depend on the dbm backend, that a new database uses the first of dbm.sqlite3, dbm.gnu, dbm.ndbm and dbm.dumb that can be imported, and that an extension may be added to the filename (Python Software Foundation, 2026); run here the new shelf was made by dbm.sqlite3 as the single file mydata, which sqlite3 could open and whichdb() named, dbm.dumb made dumbdata.bak, dumbdata.dat and dumbdata.dir, which is the Windows list of the chapter, and the lists of Windows and macOS themselves were not run.',
 'ShelfSecurity': 'The chapter says to use shelve to save data from Python programs (Sweigart, 2025); the documentation adds that, because shelve is backed by pickle, it is insecure to load a shelf from an untrusted source, since loading can execute arbitrary code, that concurrent reading and writing by two programs is not supported, that values should be fairly small, and that on macOS dbm.ndbm can silently corrupt the file on updates; the warning was read and was not demonstrated, since that would run hostile code (Python Software Foundation, 2026).',
 'PlainAlternative': 'Plain data can be saved in a format that is not tied to Python (Python Software Foundation, 2026).',
 'JsonSaving': 'The chapter as read saves data with shelve, and the tutorial presents json for lists and dictionaries: json.dump(x, f) writes and json.load(f) reads, the file must be UTF-8, and only simple types are handled without extra effort; run here json.dumps of a dictionary with a list, an integer and a tuple gave \'{"cats": ["Zophie", "Pooka", "Simon"], "count": 3, "pair": [1, 2], "5": "five"}\', reading it back gave a dictionary that was not equal to the original because the tuple had become a list and the key 5 the string \'5\', and json.dump with indent=1 and json.load round-tripped a small dictionary (Sweigart, 2025) (Python Software Foundation, 2026).',
 'ChapterPrograms': "The chapter's one project and its two practice programs put the file functions to use (Sweigart, 2025).",
 'QuizProgram': 'Project 4 writes 35 different quizzes and their answer keys to text files (Sweigart, 2025).',
 'QuizData': "Step 1 imports random, keeps the 50 states and capitals in the dictionary capitals and starts a for loop over range(35) that will make the quiz files (Sweigart, 2025); in the listing as printed the key 'West Virginia' is broken over two lines, and run as a literal newline inside the quotes the compile failed with SyntaxError: unterminated string literal (detected at line 1), while the joined key compiled, the dictionary having 50 keys and 50 different capitals (Python Software Foundation, 2026).",
 'QuizFiles': "Steps 2 to 4 open capitalsquiz<N>.txt and capitalsquiz_answers<N>.txt in write mode, write the header, shuffle a list of the states with random.shuffle(), delete the right capital from a copy of the values, choose three wrong ones with random.sample(), shuffle them with the right one, and write each question with the letters 'ABCD'[i] and the key letter 'ABCD'[answer_options.index(correct_answer)] before closing both files (Sweigart, 2025); run with random.seed(10) added for repeatability it made 70 files, each quiz having 50 questions and 200 options, and in all 35 quizzes the four options of a question were different and the letter in the key named the capital of the state asked (Python Software Foundation, 2026).",
 'QuizOutputDiffers': 'The chapter prints a quiz file with \'State Capitals Quiz (Form 1)\' and \'1. What is the capital of West Virginia?\' and an answer key of the lines \'1. D\' and \'2. C\' (Sweigart, 2025); the code it lists, run, wrote \'(Form1)\', wrote \'1. Capital of South Dakota:\' for the first question of the run with seed 10, and wrote the key as the single line 1.D2.C3.C4.B and on, because the last write has no space and no newline; a corrected writer with the question text \'What is the capital of ...?\', \'Form 1\' and f"{num + 1}. {letter}\\n" printed the lines the chapter shows and a key of 50 lines (Python Software Foundation, 2026).',
 'PracticeWork': 'The chapter ends with practice questions and two programs to write (Sweigart, 2025).',
 'MadLibs': "Practice program 1 reads a text file, asks for a word wherever ADJECTIVE, NOUN, ADVERB or VERB appears, prints the result and saves it to a new text file (Sweigart, 2025); a solution written for this study, with re.sub() and a replacement function, turned the chapter's panda text and the answers silly, chandelier, screamed and pickup truck into the chapter's sentence and saved and read it back equal, but kept the line break after 'was' where the chapter's printed result breaks the line after 'nearby', the two printed texts not being replacements word for word of each other (Python Software Foundation, 2026).",
 'RegexSearch': "Practice program 2 opens every .txt file of a folder and prints each line that matches a regular expression from the user (Sweigart, 2025); a solution written for this study, with glob('*.txt'), sorted() and enumerate(f, start=1), found 'spam' in a.txt line 1 and b.txt line 2, found also a.txt line 3 with the flag (?i), and with the pattern ^\\w+$ found the one-word lines 'bacon' and 'nothing', the .csv file being ignored (Python Software Foundation, 2026).",
 'PracticeQuestions': "The 11 practice questions ask what a relative path is relative to, what an absolute path starts with, what Path('C:/Users') / 'Al' and 'C:/Users' / 'Al' evaluate to, what os.getcwd() and os.chdir() do, what the . and .. folders are, which part of C:\\bacon\\eggs\\spam.txt is the directory and which the base name, the three modes of open(), what write mode does to an existing file, the difference between read() and readlines() and what a shelf resembles (Sweigart, 2025); run here the answers were PureWindowsPath('C:/Users/Al'), TypeError, the parent C:\\bacon\\eggs and the name spam.txt, a file opened in write mode left empty with size 0, str from read(), list from readlines(), and a shelf that is an instance of collections.abc.MutableMapping (Python Software Foundation, 2026).",
}
BEH = [
 ['Path() joins names with the separator of the operating system; Windows flavour shown with PureWindowsPath', "from pathlib import Path, PureWindowsPath, PurePosixPath\nw = PureWindowsPath('spam', 'bacon', 'eggs')\nprint(repr(w), str(w))\nprint(repr(PurePosixPath('spam', 'bacon', 'eggs')), str(PurePosixPath('spam', 'bacon', 'eggs')))\nprint(type(Path('spam', 'bacon', 'eggs')).__name__)\nmy_files = ['accounts.txt', 'details.csv', 'invite.docx']\nfor filename in my_files:\n    print(PureWindowsPath(r'C:\\Users\\Al', filename))\nprint(PureWindowsPath(r'spam\\eggs').parts, PurePosixPath(r'spam\\eggs').parts)\n", "PureWindowsPath('spam/bacon/eggs') spam\\bacon\\eggs\nPurePosixPath('spam/bacon/eggs') spam/bacon/eggs\nPosixPath\nC:\\Users\\Al\\accounts.txt\nC:\\Users\\Al\\details.csv\nC:\\Users\\Al\\invite.docx\n('spam', 'eggs') ('spam\\\\eggs',)"],
 ['the / operator joins paths; two strings raise TypeError', "from pathlib import Path, PureWindowsPath as P\nprint(repr(P('spam') / 'bacon' / 'eggs'))\nprint(repr(P('spam') / P('bacon/eggs')))\nprint(repr(P('spam') / P('bacon', 'eggs')))\nprint(repr('spam' / P('bacon')))\ntry:\n    'spam' / 'bacon'\nexcept TypeError as e:\n    print(type(e).__name__ + ': ' + str(e))\nprint(repr(Path('spam').joinpath('bacon', 'eggs')), repr(Path('spam') / '/etc'))\nimport os.path\nprint(os.path.join('spam', 'bacon', 'eggs'), os.path.join('spam', '/etc'))\n", "PureWindowsPath('spam/bacon/eggs')\nPureWindowsPath('spam/bacon/eggs')\nPureWindowsPath('spam/bacon/eggs')\nPureWindowsPath('spam/bacon')\nTypeError: unsupported operand type(s) for /: 'str' and 'str'\nPosixPath('spam/bacon/eggs') PosixPath('/etc')\nspam/bacon/eggs /etc"],
 ['current working directory, chdir and the error for a missing folder', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nos.makedirs('delicious/walnut/waffles')\nos.chdir('delicious/walnut')\nprint(Path.cwd().name, os.getcwd() == str(Path.cwd()), type(os.getcwd()).__name__, type(Path.cwd()).__name__)\ntry:\n    os.chdir('ThisFolderDoesNotExist')\nexcept FileNotFoundError as e:\n    print(type(e).__name__ + ': ' + str(e))\nprint(hasattr(Path, 'chdir'))\n", "walnut True str PosixPath\nFileNotFoundError: [Errno 2] No such file or directory: 'ThisFolderDoesNotExist'\nFalse"],
 ['the home directory is an absolute path', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nhome = Path.home()\nprint(home.is_absolute(), home == Path(os.path.expanduser('~')), home == Path('~').expanduser())\n", 'True True True'],
 ['absolute and relative paths, absolute() and resolve()', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nprint(Path.cwd().is_absolute(), Path('spam/bacon/eggs').is_absolute())\nr = Path('my/relative/path')\nprint(r.absolute() == Path.cwd() / r, (Path.cwd() / r).is_absolute())\nprint(Path('docs/../setup.py').absolute().relative_to(Path.cwd()))\nprint(Path('docs/../setup.py').resolve().relative_to(Path.cwd().resolve()))\nfrom pathlib import PureWindowsPath as W, PurePosixPath as X\nprint(W('C:/Users').is_absolute(), W('/a/b').is_absolute(), W('C:').is_absolute(), X('/a/b').is_absolute(), X('a/b').is_absolute())\nprint(Path.home() / r == Path(os.path.expanduser('~')) / r)\n", 'True False\nTrue True\ndocs/../setup.py\nsetup.py\nTrue False False True False\nTrue'],
 ['the dot and dot-dot names', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nos.makedirs('bacon/eggs')\nos.chdir('bacon/eggs')\nprint(Path('..').resolve().name, Path('.').resolve() == Path.cwd(), Path('../..').resolve() == Path.cwd().parent.parent)\nprint(Path('./spam.txt') == Path('spam.txt'), str(Path('./spam.txt')), str(Path('a/../b')))\n", 'bacon True True\nTrue spam.txt a/../b'],
 ['the parts of a filepath', "from pathlib import PureWindowsPath as W, PurePosixPath as X\np = W('C:/Users/Al/spam.txt')\nprint(repr(p.anchor), repr(p.parent), p.name, p.stem, p.suffix, repr(p.drive))\nprint(p.parts, p.parts[3], p.parts[0:2])\nc = W('C:/Users/Al/Desktop')\nprint(repr(c.parents[0]), repr(c.parents[1]), repr(c.parents[2]), len(c.parents))\nq = X('/home/al/spam.txt')\nprint(repr(q.anchor), repr(q.drive), q.parts)\na = X('archive.tar.gz')\nprint(a.suffix, a.suffixes, a.stem)\nprint(type(p.parent).__name__, type(p.name).__name__, type(p.parts).__name__)\n", "'C:\\\\' PureWindowsPath('C:/Users/Al') spam.txt spam .txt 'C:'\n('C:\\\\', 'Users', 'Al', 'spam.txt') spam.txt ('C:\\\\', 'Users')\nPureWindowsPath('C:/Users/Al') PureWindowsPath('C:/Users') PureWindowsPath('C:/') 3\n'/' '' ('/', 'home', 'al', 'spam.txt')\n.gz ['.tar', '.gz'] archive.tar\nPureWindowsPath str tuple"],
 ['deriving new paths: with_suffix, with_name, relative_to', "from pathlib import PurePosixPath as X\np = X('/home/al/reports/spam.txt')\nprint(p.with_suffix('.csv'), p.with_name('eggs.txt'), p.relative_to('/home/al'))\ntry:\n    p.relative_to('/usr')\nexcept ValueError as e:\n    print(type(e).__name__)\nprint(p.parent / (p.stem + '_backup' + p.suffix))\n", '/home/al/reports/spam.csv /home/al/reports/eggs.txt reports/spam.txt\nValueError\n/home/al/reports/spam_backup.txt'],
 ['makedirs and mkdir, with the errors of the second call', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nos.makedirs('delicious/walnut/waffles')\nprint(Path('delicious/walnut/waffles').is_dir())\ntry:\n    os.makedirs('delicious/walnut/waffles')\nexcept FileExistsError as e:\n    print(type(e).__name__)\nos.makedirs('delicious/walnut/waffles', exist_ok=True)\ntry:\n    Path('a/b').mkdir()\nexcept FileNotFoundError as e:\n    print(type(e).__name__)\nPath('a/b').mkdir(parents=True)\nPath('spam').mkdir()\ntry:\n    Path('spam').mkdir()\nexcept FileExistsError as e:\n    print(type(e).__name__)\nPath('spam').mkdir(exist_ok=True)\nprint(sorted(str(p) for p in Path('.').rglob('*') if p.is_dir()))\n", "True\nFileExistsError\nFileNotFoundError\nFileExistsError\n['a', 'a/b', 'delicious', 'delicious/walnut', 'delicious/walnut/waffles', 'spam']"],
 ['glob patterns on a small folder', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nfor n in ('1.png', '22-ap.pdf', 'cat.jpg', 'zzz.txt', 'project1.txt', 'project2.txt', 'projectX.txt', 'project10.txt', 'catproject5.txt', 'secret_project7.docx', 'notes.TXT'):\n    Path(n).write_text('x', encoding='utf-8')\nos.makedirs('sub/deeper')\nPath('sub/inner.txt').write_text('x', encoding='utf-8'); Path('sub/deeper/deep.txt').write_text('x', encoding='utf-8')\np = Path('.')\nnames = lambda pattern, **kw: sorted(str(x) for x in p.glob(pattern, **kw))\nprint(names('*.txt'))\nprint(names('project?.txt'))\nprint(names('*project?.*'))\nprint(names('*'))\nprint(names('[0-9]*'))\nprint(names('*.txt', case_sensitive=False))\nprint(names('*/*.txt'), names('**/*.txt'), sorted(str(x) for x in p.rglob('*.txt')) == names('**/*.txt'))\nprint(names('sub/'))\ng = p.glob('*.png')\nprint(type(g).__name__, list(g), list(g))\n", "['catproject5.txt', 'project1.txt', 'project10.txt', 'project2.txt', 'projectX.txt', 'zzz.txt']\n['project1.txt', 'project2.txt', 'projectX.txt']\n['catproject5.txt', 'project1.txt', 'project2.txt', 'projectX.txt', 'secret_project7.docx']\n['1.png', '22-ap.pdf', 'cat.jpg', 'catproject5.txt', 'notes.TXT', 'project1.txt', 'project10.txt', 'project2.txt', 'projectX.txt', 'secret_project7.docx', 'sub', 'zzz.txt']\n['1.png', '22-ap.pdf']\n['catproject5.txt', 'notes.TXT', 'project1.txt', 'project10.txt', 'project2.txt', 'projectX.txt', 'zzz.txt']\n['sub/inner.txt'] ['catproject5.txt', 'project1.txt', 'project10.txt', 'project2.txt', 'projectX.txt', 'sub/deeper/deep.txt', 'sub/inner.txt', 'zzz.txt'] True\n['sub']\nmap [PosixPath('1.png')] []"],
 ['exists, is_file and is_dir, for a file, a folder and nothing', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nPath('calc.exe').write_bytes(b'MZ')\nos.mkdir('Windows')\nok = {'file': Path('calc.exe'), 'folder': Path('Windows'), 'missing': Path('This/Folder/Does/Not/Exist')}\nfor k, v in ok.items():\n    print(k, v.exists(), v.is_file(), v.is_dir(), os.path.exists(v), os.path.isfile(v), os.path.isdir(v))\n", 'file True True False True True False\nfolder True False True True False True\nmissing False False False False False False'],
 ['stat gives size and timestamps; a modified time can be set by hand', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport time\np = Path('calc.txt'); p.write_text('Hello, world!', encoding='utf-8')\ns = p.stat()\nprint(s.st_size, p.stat().st_size / 1024, type(s).__name__)\nos.utime(p, (1712627129, 1712627129))\nprint(p.stat().st_mtime, time.asctime(time.gmtime(p.stat().st_mtime)))\nprint(all(hasattr(s, a) for a in ('st_size', 'st_mtime', 'st_ctime', 'st_atime')))\n", '13 0.0126953125 stat_result\n1712627129.0 Tue Apr  9 01:45:29 2024\nTrue'],
 ['write_text and read_text: the number returned counts characters, not bytes', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\np = Path('spam.txt')\nprint(p.write_text('Hello, world!'), p.read_text())\nprint(p.write_text('caf\\u00e9', encoding='utf-8'), p.stat().st_size, p.read_bytes())\nprint(p.write_text('again', encoding='utf-8'), repr(p.read_text(encoding='utf-8')))\n", "13 Hello, world!\n4 5 b'caf\\xc3\\xa9'\n5 'again'"],
 ["open in write, append and read mode: the chapter's bacon.txt session", "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nbacon_file = open('bacon.txt', 'w', encoding='UTF-8')\nprint(bacon_file.write('Hello, world!\\n'))\nbacon_file.close()\nbacon_file = open('bacon.txt', 'a', encoding='UTF-8')\nprint(bacon_file.write('Bacon is not a vegetable.'))\nbacon_file.close()\nbacon_file = open('bacon.txt', encoding='UTF-8')\ncontent = bacon_file.read()\nbacon_file.close()\nprint(content)\nwith open('bacon.txt', 'w', encoding='UTF-8') as f:\n    f.write('new')\nprint(repr(Path('bacon.txt').read_text(encoding='UTF-8')))\nwith open('fresh.txt', 'a', encoding='UTF-8') as f:\n    f.write('made by append')\nprint(Path('fresh.txt').read_text(encoding='UTF-8'))\n", "14\n25\nHello, world!\nBacon is not a vegetable.\n'new'\nmade by append"],
 ['the modes r, w, a, x, r+ and their errors', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport io\nPath('m.txt').write_text('abc', encoding='utf-8')\nwith open('m.txt', 'r', encoding='utf-8') as f:\n    try:\n        f.write('x')\n    except io.UnsupportedOperation as e:\n        print(type(e).__name__ + ': ' + str(e))\nwith open('m.txt', 'w', encoding='utf-8') as f:\n    try:\n        f.read()\n    except io.UnsupportedOperation as e:\n        print(type(e).__name__ + ': ' + str(e))\ntry:\n    open('missing.txt', encoding='utf-8')\nexcept FileNotFoundError as e:\n    print(type(e).__name__, e.errno)\ntry:\n    open('m.txt', 'x', encoding='utf-8')\nexcept FileExistsError as e:\n    print(type(e).__name__)\nwith open('n.txt', 'x', encoding='utf-8') as f:\n    print(f.mode, f.write('made'))\nwith open('n.txt', 'r+', encoding='utf-8') as f:\n    print(f.read(), f.write('!'), end=' ')\nprint(Path('n.txt').read_text(encoding='utf-8'), io.UnsupportedOperation.__mro__[1].__name__)\n", 'UnsupportedOperation: not writable\nUnsupportedOperation: not readable\nFileNotFoundError 2\nFileExistsError\nx 4\nmade 1 made! OSError'],
 ["read, readlines, readline and the position in the file: the chapter's sonnet", 'import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir(\'/\'), _t.cleanup()))\nPath(\'sonnet29.txt\').write_text("When, in disgrace with fortune and men\'s eyes,\\nI all alone beweep my outcast state,\\nAnd trouble deaf heaven with my bootless cries,\\nAnd look upon myself and curse my fate,", encoding=\'UTF-8\')\nf = open(\'sonnet29.txt\', encoding=\'UTF-8\')\nprint(f.readlines())\nprint(f.readlines(), repr(f.read()))\nf.seek(0)\nprint(repr(f.readline()), repr(f.read(5)), repr(f.read(3)))\nf.seek(0)\nprint(len(f.read()), repr(f.read()))\nf.close()\nwith open(\'sonnet29.txt\', encoding=\'UTF-8\') as f:\n    print([line.rstrip(\'\\n\')[:12] for line in f])\nwith open(\'sonnet29.txt\', encoding=\'UTF-8\') as f:\n    print(f.read().splitlines() == [l.rstrip(\'\\n\') for l in open(\'sonnet29.txt\', encoding=\'UTF-8\')])\nwith open(\'sonnet29.txt\', encoding=\'UTF-8\') as f:\n    n = 0\n    while line := f.readline():\n        n += 1\n    print(n, repr(f.readline()))\n', '["When, in disgrace with fortune and men\'s eyes,\\n", \'I all alone beweep my outcast state,\\n\', \'And trouble deaf heaven with my bootless cries,\\n\', \'And look upon myself and curse my fate,\']\n[] \'\'\n"When, in disgrace with fortune and men\'s eyes,\\n" \'I all\' \' al\'\n171 \'\'\n[\'When, in dis\', \'I all alone \', \'And trouble \', \'And look upo\']\nTrue\n4 \'\''],
 ['write adds no newline, takes only strings, print(file=) does', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nwith open('w.txt', 'w', encoding='utf-8') as f:\n    f.write('a')\n    f.write('b')\n    print('c', file=f)\n    try:\n        f.write(42)\n    except TypeError as e:\n        print(type(e).__name__ + ': ' + str(e))\n    f.write(str(42) + '\\n')\n    f.writelines(['x\\n', 'y\\n'])\nprint(repr(Path('w.txt').read_text(encoding='utf-8')))\n", "TypeError: write() argument must be str, not int\n'abc\\n42\\nx\\ny\\n'"],
 ['close, with, and using a closed file', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nf = open('c.txt', 'w', encoding='utf-8')\nprint(f.closed, f.write('data'), f.closed)\nprint(repr(Path('c.txt').read_text(encoding='utf-8')))\nf.close()\nprint(f.closed, repr(Path('c.txt').read_text(encoding='utf-8')))\ntry:\n    f.write('more')\nexcept ValueError as e:\n    print(type(e).__name__ + ': ' + str(e))\nwith open('c.txt', encoding='utf-8') as g:\n    body = g.read()\nprint(g.closed, body)\ntry:\n    with open('c.txt', encoding='utf-8') as g:\n        raise RuntimeError('boom')\nexcept RuntimeError:\n    print(g.closed)\ndef first_line(name):\n    with open(name, encoding='utf-8') as h:\n        return h, h.readline()\nh, line = first_line('c.txt')\nprint(h.closed, line)\nprint(hasattr(g, '__enter__'), hasattr(g, '__exit__'))\n", "False 4 False\n''\nTrue 'data'\nValueError: I/O operation on closed file.\nTrue data\nTrue\nTrue data\nTrue True"],
 ['the encoding argument: a wrong encoding raises or garbles', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nPath('u.txt').write_text('caf\\u00e9', encoding='utf-8')\nprint(Path('u.txt').read_bytes())\nfor enc in ('utf-8', 'latin-1', 'cp1252'):\n    print(enc, ascii(Path('u.txt').read_text(encoding=enc)))\ntry:\n    Path('u.txt').read_text(encoding='ascii')\nexcept UnicodeDecodeError as e:\n    print(type(e).__name__ + ': ' + str(e))\nprint(ascii(open('u.txt', encoding='ascii', errors='replace').read()))\ntry:\n    Path('v.txt').write_text('caf\\u00e9', encoding='ascii')\nexcept UnicodeEncodeError as e:\n    print(type(e).__name__)\nwith open('u.txt', encoding='UTF-8') as f:\n    print(f.encoding, f.mode)\nimport locale\nwith open('u.txt') as f:\n    print(f.encoding.lower().replace('-', '') == locale.getencoding().lower().replace('-', '') or f.encoding)\n", "b'caf\\xc3\\xa9'\nutf-8 'caf\\xe9'\nlatin-1 'caf\\xc3\\xa9'\ncp1252 'caf\\xc3\\xa9'\nUnicodeDecodeError: 'ascii' codec can't decode byte 0xc3 in position 3: ordinal not in range(128)\n'caf\\ufffd\\ufffd'\nUnicodeEncodeError\nUTF-8 r\nTrue"],
 ['the default encoding can draw an EncodingWarning when asked', 'import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir(\'/\'), _t.cleanup()))\nimport subprocess, sys\ncode = "open(\'x.txt\', \'w\').close()"\nr = subprocess.run([sys.executable, \'-X\', \'warn_default_encoding\', \'-c\', code], capture_output=True, text=True)\nprint(r.returncode, \'EncodingWarning\' in r.stderr)\nr = subprocess.run([sys.executable, \'-X\', \'warn_default_encoding\', \'-c\', "open(\'x.txt\', \'w\', encoding=\'utf-8\').close()"], capture_output=True, text=True)\nprint(r.returncode, r.stderr == \'\')\n', '0 True\n0 True'],
 ['text mode translates line endings; newline= controls it; binary mode does not', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nPath('n1.txt').write_text('a\\nb', newline='\\r\\n', encoding='utf-8')\nprint(Path('n1.txt').read_bytes())\nprint(repr(Path('n1.txt').read_text(encoding='utf-8')), repr(Path('n1.txt').read_text(encoding='utf-8', newline='')))\nwith open('n2.txt', 'w', encoding='utf-8', newline='') as f:\n    f.write('a\\nb\\r\\n')\nprint(Path('n2.txt').read_bytes())\nprint(os.linesep in ('\\n', '\\r\\n'))\n", "b'a\\r\\nb'\n'a\\nb' 'a\\r\\nb'\nb'a\\nb\\r\\n'\nTrue"],
 ['binary mode reads and writes bytes and takes no encoding', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nwith open('b.bin', 'wb') as f:\n    print(f.write(bytes([0, 1, 2, 255])))\nwith open('b.bin', 'rb') as f:\n    data = f.read()\nprint(data, type(data).__name__, list(data))\ntry:\n    open('b.bin', 'rb', encoding='utf-8')\nexcept ValueError as e:\n    print(type(e).__name__ + ': ' + str(e))\ntry:\n    with open('b.bin', 'wb') as f:\n        f.write('text')\nexcept TypeError as e:\n    print(type(e).__name__ + ': ' + str(e))\nwith open('b.bin', 'rb') as f:\n    print(type(f).__name__)\nwith open('b.bin', encoding='latin-1') as f:\n    print(type(f).__name__)\n", "4\nb'\\x00\\x01\\x02\\xff' bytes [0, 1, 2, 255]\nValueError: binary mode doesn't take an encoding argument\nTypeError: a bytes-like object is required, not 'str'\nBufferedReader\nTextIOWrapper"],
 ["shelve: the chapter's session with the cats", "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport shelve\nshelf_file = shelve.open('mydata')\nshelf_file['cats'] = ['Zophie', 'Pooka', 'Simon']\nshelf_file.close()\nprint(sorted(os.listdir('.')))\nshelf_file = shelve.open('mydata')\nprint(type(shelf_file))\nprint(shelf_file['cats'])\nshelf_file.close()\nshelf_file = shelve.open('mydata')\nprint(list(shelf_file.keys()))\nprint(list(shelf_file.values()))\nprint(type(shelf_file.keys()).__name__, 'cats' in shelf_file, len(shelf_file))\nshelf_file.close()\nimport dbm\nprint(dbm.whichdb('mydata'))\n", "['mydata']\n<class 'shelve.DbfilenameShelf'>\n['Zophie', 'Pooka', 'Simon']\n['cats']\n[['Zophie', 'Pooka', 'Simon']]\nKeysView True 1\ndbm.sqlite3"],
 ['a shelf is like a dictionary: keys are strings, a value is a copy, del and KeyError', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport shelve\nwith shelve.open('d') as s:\n    s['n'] = 1; s['t'] = (1, 2); s['set'] = {3, 4}; s['nested'] = {'a': [1, {'b': 2}]}\n    try:\n        s[1] = 'x'\n    except AttributeError as e:\n        print(type(e).__name__ + ': ' + str(e))\n    try:\n        s['missing']\n    except KeyError as e:\n        print(type(e).__name__, e)\n    del s['n']\n    print(sorted(s), s.get('n', 'gone'), s['t'], s['set'], s['nested'])\n    a = s['t']\n    print(a is s['t'], a == s['t'])\ntry:\n    s['x'] = 1\nexcept ValueError as e:\n    print(type(e).__name__ + ': ' + str(e))\n", "AttributeError: 'int' object has no attribute 'encode'\nKeyError b'missing'\n['nested', 'set', 't'] gone (1, 2) {3, 4} {'a': [1, {'b': 2}]}\nFalse True\nValueError: invalid operation on closed shelf"],
 ['a shelf does not see a list changed in place unless writeback=True', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport shelve\nwith shelve.open('w1') as s:\n    s['cats'] = ['Zophie']\nwith shelve.open('w1') as s:\n    s['cats'].append('Pooka')\nwith shelve.open('w1') as s:\n    print(s['cats'])\n    cats = s['cats']; cats.append('Pooka'); s['cats'] = cats\nwith shelve.open('w1') as s:\n    print(s['cats'])\nwith shelve.open('w1', writeback=True) as s:\n    s['cats'].append('Simon')\nwith shelve.open('w1') as s:\n    print(s['cats'])\n", "['Zophie']\n['Zophie', 'Pooka']\n['Zophie', 'Pooka', 'Simon']"],
 ['the files of a dbm database depend on the backend: dbm.dumb makes three, dbm.sqlite3 one', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport dbm.dumb, dbm.sqlite3, shelve\nd = dbm.dumb.open('dumbdata', 'c'); d['k'] = 'v'; d.close()\nprint(sorted(f for f in os.listdir('.') if f.startswith('dumbdata')))\nd = dbm.sqlite3.open('sqldata', 'c'); d['k'] = 'v'; d.close()\nprint(sorted(f for f in os.listdir('.') if f.startswith('sqldata')), dbm.whichdb('sqldata'), dbm.whichdb('dumbdata'))\nimport sqlite3\nc = sqlite3.connect('sqldata'); print(c.execute('select count(*) from Dict').fetchone()); c.close()\nwith shelve.open('viadefault') as s:\n    s['a'] = 1\nprint(dbm.whichdb('viadefault'), sorted(f for f in os.listdir('.') if f.startswith('viadefault')))\n", "['dumbdata.bak', 'dumbdata.dat', 'dumbdata.dir']\n['sqldata'] dbm.sqlite3 dbm.dumb\n(1,)\ndbm.sqlite3 ['viadefault']"],
 ['json keeps plain data in a text file anyone can read; tuples come back as lists', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport json\ndata = {'cats': ['Zophie', 'Pooka', 'Simon'], 'count': 3, 'pair': (1, 2), 5: 'five'}\nPath('data.json').write_text(json.dumps(data), encoding='utf-8')\nprint(Path('data.json').read_text(encoding='utf-8'))\nback = json.loads(Path('data.json').read_text(encoding='utf-8'))\nprint(back, back == data)\nwith open('data2.json', 'w', encoding='utf-8') as f:\n    json.dump({'cats': ['Zophie']}, f, indent=1)\nwith open('data2.json', encoding='utf-8') as f:\n    print(json.load(f))\n", '{"cats": ["Zophie", "Pooka", "Simon"], "count": 3, "pair": [1, 2], "5": "five"}\n{\'cats\': [\'Zophie\', \'Pooka\', \'Simon\'], \'count\': 3, \'pair\': [1, 2], \'5\': \'five\'} False\n{\'cats\': [\'Zophie\']}'],
 ['Project 4, the random quiz generator, as printed in steps 1 to 4 and then checked', 'import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir(\'/\'), _t.cleanup()))\ncapitals = {\'Alabama\': \'Montgomery\', \'Alaska\': \'Juneau\', \'Arizona\': \'Phoenix\', \'Arkansas\': \'Little Rock\', \'California\': \'Sacramento\', \'Colorado\': \'Denver\', \'Connecticut\': \'Hartford\', \'Delaware\': \'Dover\', \'Florida\': \'Tallahassee\', \'Georgia\': \'Atlanta\', \'Hawaii\': \'Honolulu\', \'Idaho\': \'Boise\', \'Illinois\': \'Springfield\', \'Indiana\': \'Indianapolis\', \'Iowa\': \'Des Moines\', \'Kansas\': \'Topeka\', \'Kentucky\': \'Frankfort\', \'Louisiana\': \'Baton Rouge\', \'Maine\': \'Augusta\', \'Maryland\': \'Annapolis\', \'Massachusetts\': \'Boston\', \'Michigan\': \'Lansing\', \'Minnesota\': \'Saint Paul\', \'Mississippi\': \'Jackson\', \'Missouri\': \'Jefferson City\', \'Montana\': \'Helena\', \'Nebraska\': \'Lincoln\', \'Nevada\': \'Carson City\', \'New Hampshire\': \'Concord\', \'New Jersey\': \'Trenton\', \'New Mexico\': \'Santa Fe\', \'New York\': \'Albany\', \'North Carolina\': \'Raleigh\', \'North Dakota\': \'Bismarck\', \'Ohio\': \'Columbus\', \'Oklahoma\': \'Oklahoma City\', \'Oregon\': \'Salem\', \'Pennsylvania\': \'Harrisburg\', \'Rhode Island\': \'Providence\', \'South Carolina\': \'Columbia\', \'South Dakota\': \'Pierre\', \'Tennessee\': \'Nashville\', \'Texas\': \'Austin\', \'Utah\': \'Salt Lake City\', \'Vermont\': \'Montpelier\', \'Virginia\': \'Richmond\', \'Washington\': \'Olympia\', \'West Virginia\': \'Charleston\', \'Wisconsin\': \'Madison\', \'Wyoming\': \'Cheyenne\'}\nimport random\nrandom.seed(10)\nfor quiz_num in range(35):\n    quiz_file = open(f\'capitalsquiz{quiz_num + 1}.txt\', \'w\', encoding=\'UTF-8\')\n    answer_file = open(f\'capitalsquiz_answers{quiz_num + 1}.txt\', \'w\', encoding=\'UTF-8\')\n    quiz_file.write(\'Name:\\n\\nDate:\\n\\nPeriod:\\n\\n\')\n    quiz_file.write((\' \' * 20) + f\'State Capitals Quiz (Form{quiz_num + 1})\')\n    quiz_file.write(\'\\n\\n\')\n    states = list(capitals.keys())\n    random.shuffle(states)\n    for num in range(50):\n        correct_answer = capitals[states[num]]\n        wrong_answers = list(capitals.values())\n        del wrong_answers[wrong_answers.index(correct_answer)]\n        wrong_answers = random.sample(wrong_answers, 3)\n        answer_options = wrong_answers + [correct_answer]\n        random.shuffle(answer_options)\n        quiz_file.write(f\'{num + 1}. Capital of {states[num]}:\\n\')\n        for i in range(4):\n            quiz_file.write(f"    {\'ABCD\'[i]}. {answer_options[i]}\\n")\n        quiz_file.write(\'\\n\')\n        answer_file.write(f"{num + 1}.{\'ABCD\'[answer_options.index(correct_answer)]}")\n    quiz_file.close()\n    answer_file.close()\n\nimport re\nnames = sorted(os.listdir(\'.\'))\nprint(len(names), len([n for n in names if n.startswith(\'capitalsquiz_answers\')]), len(capitals), len(set(capitals.values())))\ntext = Path(\'capitalsquiz1.txt\').read_text(encoding=\'UTF-8\')\nprint(text.split(\'\\n\')[6].strip(), \'|\', text.split(\'\\n\')[8])\nprint(len(re.findall(r\'^\\d+\\. Capital of\', text, re.M)), len(re.findall(r\'^    [ABCD]\\. \', text, re.M)))\nkey = Path(\'capitalsquiz_answers1.txt\').read_text(encoding=\'UTF-8\')\nprint(len(key.splitlines()), key[:12], \'|\', \'What is the capital\' in text)\nok = 0\nfor n in range(1, 36):\n    q = Path(f\'capitalsquiz{n}.txt\').read_text(encoding=\'UTF-8\')\n    k = Path(f\'capitalsquiz_answers{n}.txt\').read_text(encoding=\'UTF-8\')\n    letters = dict(re.findall(r\'(\\d+)\\.([ABCD])\', k))\n    blocks = re.findall(r\'(\\d+)\\. Capital of (.*?):\\n((?:    [ABCD]\\. .*\\n){4})\', q)\n    assert len(blocks) == 50 and len(letters) == 50\n    for num, state, opts in blocks:\n        chosen = dict(re.findall(r\'    ([ABCD])\\. (.*)\', opts))\n        assert chosen[letters[num]] == capitals[state]\n        assert len(set(chosen.values())) == 4\n    assert len({s for _, s, _ in blocks}) == 50\n    ok += 1\nprint(ok, \'quizzes with a correct key\')\n', '70 35 50 50\nState Capitals Quiz (Form1) | 1. Capital of South Dakota:\n50 200\n1 1.D2.C3.C4.B | False\n35 quizzes with a correct key'],
 ["the listing of step 1 as printed splits the key 'West Virginia' across two lines", 'src = "capitals = {\'Virginia\': \'Richmond\', \'Washington\': \'Olympia\', \'West\\nVirginia\':\'Charleston\', \'Wisconsin\': \'Madison\'}"\ntry:\n    compile(src, \'listing\', \'exec\')\nexcept SyntaxError as e:\n    print(type(e).__name__ + \': \' + e.msg)\nprint(compile(src.replace("West\\nVirginia", \'West Virginia\'), \'listing\', \'exec\') is not None)\n', 'SyntaxError: unterminated string literal (detected at line 1)\nTrue'],
 ['a corrected quiz writer prints what the chapter shows: the question text, Form 1 and one answer per line', 'import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir(\'/\'), _t.cleanup()))\ncapitals = {\'Alabama\': \'Montgomery\', \'Alaska\': \'Juneau\', \'Arizona\': \'Phoenix\', \'Arkansas\': \'Little Rock\', \'California\': \'Sacramento\', \'Colorado\': \'Denver\', \'Connecticut\': \'Hartford\', \'Delaware\': \'Dover\', \'Florida\': \'Tallahassee\', \'Georgia\': \'Atlanta\', \'Hawaii\': \'Honolulu\', \'Idaho\': \'Boise\', \'Illinois\': \'Springfield\', \'Indiana\': \'Indianapolis\', \'Iowa\': \'Des Moines\', \'Kansas\': \'Topeka\', \'Kentucky\': \'Frankfort\', \'Louisiana\': \'Baton Rouge\', \'Maine\': \'Augusta\', \'Maryland\': \'Annapolis\', \'Massachusetts\': \'Boston\', \'Michigan\': \'Lansing\', \'Minnesota\': \'Saint Paul\', \'Mississippi\': \'Jackson\', \'Missouri\': \'Jefferson City\', \'Montana\': \'Helena\', \'Nebraska\': \'Lincoln\', \'Nevada\': \'Carson City\', \'New Hampshire\': \'Concord\', \'New Jersey\': \'Trenton\', \'New Mexico\': \'Santa Fe\', \'New York\': \'Albany\', \'North Carolina\': \'Raleigh\', \'North Dakota\': \'Bismarck\', \'Ohio\': \'Columbus\', \'Oklahoma\': \'Oklahoma City\', \'Oregon\': \'Salem\', \'Pennsylvania\': \'Harrisburg\', \'Rhode Island\': \'Providence\', \'South Carolina\': \'Columbia\', \'South Dakota\': \'Pierre\', \'Tennessee\': \'Nashville\', \'Texas\': \'Austin\', \'Utah\': \'Salt Lake City\', \'Vermont\': \'Montpelier\', \'Virginia\': \'Richmond\', \'Washington\': \'Olympia\', \'West Virginia\': \'Charleston\', \'Wisconsin\': \'Madison\', \'Wyoming\': \'Cheyenne\'}\nimport random\nrandom.seed(10)\nstates = list(capitals.keys()); random.shuffle(states)\nwith open(\'quiz.txt\', \'w\', encoding=\'UTF-8\') as quiz_file, open(\'key.txt\', \'w\', encoding=\'UTF-8\') as answer_file:\n    quiz_file.write(\'Name:\\n\\nDate:\\n\\nPeriod:\\n\\n\')\n    quiz_file.write((\' \' * 20) + \'State Capitals Quiz (Form 1)\\n\\n\')\n    for num in range(50):\n        correct = capitals[states[num]]\n        wrong = [c for c in capitals.values() if c != correct]\n        options = random.sample(wrong, 3) + [correct]\n        random.shuffle(options)\n        quiz_file.write(f\'{num + 1}. What is the capital of {states[num]}?\\n\')\n        for i in range(4):\n            quiz_file.write(f"    {\'ABCD\'[i]}. {options[i]}\\n")\n        quiz_file.write(\'\\n\')\n        answer_file.write(f"{num + 1}. {\'ABCD\'[options.index(correct)]}\\n")\nlines = Path(\'quiz.txt\').read_text(encoding=\'UTF-8\').split(\'\\n\')\nprint(lines[6].strip()); print(lines[8]); print(len(lines[9:13]))\nprint(Path(\'key.txt\').read_text(encoding=\'UTF-8\').splitlines()[:2], len(Path(\'key.txt\').read_text(encoding=\'UTF-8\').splitlines()))\n', "State Capitals Quiz (Form 1)\n1. What is the capital of South Dakota?\n4\n['1. D', '2. C'] 50"],
 ["practice program 1, Mad Libs: the chapter's example text and answers", "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport re\ndef mad_libs(template, answers):\n    answers = iter(answers)\n    return re.sub(r'\\b(ADJECTIVE|NOUN|ADVERB|VERB)\\b', lambda m: next(answers), template)\ntext = 'The ADJECTIVE panda walked to the NOUN and then VERB. A nearby NOUN was\\nunaffected by these events.'\nPath('panda.txt').write_text(text, encoding='utf-8')\nresult = mad_libs(Path('panda.txt').read_text(encoding='utf-8'), ['silly', 'chandelier', 'screamed', 'pickup truck'])\nPath('panda_filled.txt').write_text(result, encoding='utf-8')\nprint(result)\nprint(Path('panda_filled.txt').read_text(encoding='utf-8') == result)\nprint(mad_libs('ADVERB VERB', ['quickly', 'ran']), mad_libs('no blanks here', []))\n", 'The silly panda walked to the chandelier and then screamed. A nearby pickup truck was\nunaffected by these events.\nTrue\nquickly ran no blanks here'],
 ['practice program 2, regex search over the .txt files of a folder', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nimport re\nPath('a.txt').write_text('spam and eggs\\nbacon\\nSPAM again\\n', encoding='utf-8')\nPath('b.txt').write_text('nothing\\nspam spam\\n', encoding='utf-8')\nPath('c.csv').write_text('spam,1\\n', encoding='utf-8')\ndef search(folder, pattern):\n    rx = re.compile(pattern)\n    hits = []\n    for path in sorted(Path(folder).glob('*.txt')):\n        with open(path, encoding='utf-8') as f:\n            for number, line in enumerate(f, start=1):\n                if rx.search(line):\n                    hits.append(f'{path.name}:{number}: {line.rstrip()}')\n    return hits\nprint(search('.', r'spam'))\nprint(search('.', r'(?i)spam'))\nprint(search('.', r'^\\w+$'))\n", "['a.txt:1: spam and eggs', 'b.txt:2: spam spam']\n['a.txt:1: spam and eggs', 'a.txt:3: SPAM again', 'b.txt:2: spam spam']\n['a.txt:2: bacon', 'b.txt:1: nothing']"],
 ['the practice questions of the chapter, answered by running', "import os, tempfile, atexit\nfrom pathlib import Path\n_t = tempfile.TemporaryDirectory()\nos.chdir(_t.name)\natexit.register(lambda: (os.chdir('/'), _t.cleanup()))\nfrom pathlib import PureWindowsPath as W\nprint(repr(W('C:/Users') / 'Al'))\ntry:\n    'C:/Users' / 'Al'\nexcept TypeError as e:\n    print(type(e).__name__)\np = W(r'C:\\bacon\\eggs\\spam.txt')\nprint(p.parent, p.name)\nprint(os.getcwd() == str(Path.cwd()))\nPath('t.txt').write_text('keep', encoding='utf-8')\nopen('t.txt', 'w', encoding='utf-8').close()\nprint(repr(Path('t.txt').read_text(encoding='utf-8')), Path('t.txt').stat().st_size)\nPath('t.txt').write_text('one\\ntwo', encoding='utf-8')\nwith open('t.txt', encoding='utf-8') as f:\n    print(type(f.read()).__name__, end=' ')\nwith open('t.txt', encoding='utf-8') as f:\n    print(type(f.readlines()).__name__)\nimport shelve, collections.abc\nwith shelve.open('q') as s:\n    print(isinstance(s, collections.abc.MutableMapping))\n", "PureWindowsPath('C:/Users/Al')\nTypeError\nC:\\bacon\\eggs spam.txt\nTrue\n'' 0\nstr list\nTrue"],
]
